"use client";

import { useState } from "react";

/** Switches between the birth chart (D1) and navamsa (D9) drawings. SVGs are generated by our engine. */
export function ChartTabs({ d1, d9 }: { d1: string; d9: string }) {
  const [tab, setTab] = useState<"d1" | "d9">("d1");
  const tabs = [
    { id: "d1" as const, label: "Birth chart", sub: "D1 · Rashi" },
    { id: "d9" as const, label: "Navamsa", sub: "D9 · inner strength, marriage" },
  ];
  return (
    <div>
      <div role="tablist" aria-label="Chart" className="mb-4 grid grid-cols-2 gap-1 rounded-full border border-line bg-surface-2 p-1">
        {tabs.map((t) => (
          <button
            key={t.id}
            role="tab"
            aria-selected={tab === t.id}
            onClick={() => setTab(t.id)}
            className={`rounded-full px-3 py-2 text-sm font-medium transition ${tab === t.id ? "bg-surface text-ink shadow-sm" : "text-muted"}`}
          >
            {t.label}
          </button>
        ))}
      </div>
      <div
        role="tabpanel"
        className="mx-auto aspect-square w-full max-w-sm text-ink [&_svg]:h-full [&_svg]:w-full"
        dangerouslySetInnerHTML={{ __html: tab === "d1" ? d1 : d9 }}
      />
      <p className="mt-3 text-center text-xs text-muted">
        {tabs.find((t) => t.id === tab)!.sub}. North Indian style: house 1 is the top diamond, numbers are signs (1 = Aries).
      </p>
    </div>
  );
}
